"""Vocabulary expansion, lighting / camera / environment / style / pose files (see vocab_face.py for the method)."""
import itertools
from vocab_lib import S, sample, seed_of, consistent
from vocab_face import R, reg, dims

def P(fmt, *axes):
    return [fmt.format(*c) for c in itertools.product(*axes)]
def regp(name, fn): R[name] = fn

