LENS_BY_RANGE = [
 (14, 20, S("ultra-wide lens, rectilinear ultra-wide prime, fisheye lens, wide cinema prime"), S("at f/2.8, at f/4, at f/5.6, at f/8, at f/11")),
 (24, 35, S("wide-angle prime, wide-angle zoom, anamorphic wide lens, street-photography prime, cinema prime, vintage wide prime"), S("at f/1.4, at f/1.8, at f/2, at f/2.8, at f/4, at f/5.6, at f/8")),
 (40, 58, S("standard prime lens, fast standard prime, vintage standard prime, cinema prime, pancake lens, soft-focus lens"), S("at f/1.2, at f/1.4, at f/1.8, at f/2, at f/2.8, at f/4, at f/5.6, at f/8")),
 (65, 135, S("portrait prime, fast portrait prime, short telephoto prime, macro lens, vintage portrait lens, cinema prime, soft-focus portrait lens"), S("at f/1.2, at f/1.4, at f/1.8, at f/2, at f/2.8, at f/4, at f/5.6")),
 (150, 600, S("telephoto lens, telephoto prime, telephoto zoom, long cinema telephoto, super-telephoto lens"), S("at f/2.8, at f/4, at f/5.6, at f/8")),
]
FOCALS = {(14, 20): [14, 16, 18, 20], (24, 35): [24, 28, 35], (40, 58): [40, 50, 58], (65, 135): [65, 75, 85, 105, 135], (150, 600): [150, 200, 300, 400, 600]}
CL_FEEL = S("with natural perspective, with compressed perspective, with stretched perspective, with gentle distortion, with minimal distortion, with a slight vignette, with a clean edge-to-edge look, with a dreamy glow, with crisp micro-contrast, with a vintage look, with a smooth rendering, with a painterly rendering")
def _lens(o):
    out = []
    for lo, hi, types, aps in LENS_BY_RANGE:
        for f in FOCALS[(lo, hi)]:
            for t in types:
                for a in aps:
                    for fe in CL_FEEL:
                        if 'ultra-wide' in t or 'fisheye' in t:
                            if fe in ('with compressed perspective', 'with a dreamy glow'): continue
                        if lo >= 150 and fe in ('with stretched perspective', 'with minimal distortion'): continue
                        out.append(f'{f}mm {t} {a}, {fe}')
    return sample(out, 340, 'cam_lens')
regp('cam_lens', _lens)

