regp('pose_twist', lambda o: sample(P('{0}, {1}', TW, TW_Q), 300, 'pose_twist') + TW)

WT = S("weight evenly on both feet, weight on the left leg, weight on the right leg, weight on the heels, weight on the toes, weight forward, weight back, weight low and grounded, weight light and lifted, weight resting on a wall, weight resting on a chair back, weight resting on the hands, weight resting on the elbows, weight resting on the hips, weight shifted mid-step, weight in a deep lunge, weight in a wide stance, weight in a narrow stance, weight on one knee, weight on both knees, weight on the seat, weight on the side of the hip, weight balanced on one foot, weight carried through the shoulders, weight sunk into a chair, weight perched at the edge of a seat, weight leaning on a railing, weight leaning on a doorframe, weight settling into a hammock, weight spread across the back")
